function fm_index_read(string $file): string {
    if (! is_file($file) || ! is_readable($file)) return '';
    $contents = file_get_contents($file);
    return is_string($contents) ? $contents : '';
}
function fm_index_escape(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function fm_index_url(string $value): string { return preg_match('#^https?://#i', $value) ? fm_index_escape($value) : '#'; }
function fm_index_header(string $contents, string $field): string {
    return preg_match('/^[ \t\/*#@]*' . preg_quote($field, '/') . ':\s*(.+)$/mi', $contents, $matches) ? trim((string) $matches[1]) : '';
}
function fm_index_json(string $file): array { $data = json_decode(fm_index_read($file), true); return is_array($data) ? $data : array(); }
function fm_index_templates(string $directory): array {
    if (! is_dir($directory)) return array();
    $templates = array();
    foreach (glob($directory . DIRECTORY_SEPARATOR . '*.php') ?: array() as $file) {
        $contents = fm_index_read($file); $name = fm_index_header($contents, 'Template Name');
        if ($name === '') continue;
        $description = fm_index_header($contents, 'Beschreibung') ?: fm_index_header($contents, 'Description');
        $templates[] = array('name' => $name, 'description' => $description);
    }
    usort($templates, static fn(array $a, array $b): int => strnatcasecmp($a['name'], $b['name']));
    return $templates;
}
function fm_index_history(string $file, int $limit = 4): array {
    $entries = array(); $current = null;
    foreach (preg_split('/\R/', fm_index_read($file)) ?: array() as $line) {
        $line = trim((string) $line);
        if (preg_match('/^##\s+(.+)$/', $line, $matches)) {
            if (is_array($current)) { $entries[] = $current; if (count($entries) >= $limit) break; }
            $current = array('title' => trim($matches[1]), 'changes' => array()); continue;
        }
        if (is_array($current) && preg_match('/^-\s+(.+)$/', $line, $matches)) $current['changes'][] = trim($matches[1]);
    }
    if (is_array($current) && count($entries) < $limit) $entries[] = $current;
    return $entries;
}

